from django.shortcuts import render
from django.http import HttpResponse
from transaction.models import *
from attendance.utils import *
from django.contrib.auth.models import User

def index(request):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	h={}
	for i in Transaction.objects.filter(tdate__date=datetime.now().date(), status=1).distinct("register_id"):
		h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]=[i.level, i.service]
	j=Total()
	j.date=datetime.now().date().strftime("%Y-%m-%d")
	g=j.CSTotal()
	k=datetime.date(datetime.now())
	o=datetime.date(datetime.now()).strftime("%A")
	return render(request, 'attendance/index.html', {'h':h, 'g':g, 'k':k, 'o':o, 'nxtgnuser':nxtgnuser}, content_type='text/html')


def service(request, u):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	h={}
	for i in Transaction.objects.filter(tdate__date=datetime.now().date(), service=u, status=1).distinct("register_id"):
		h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]=[i.level, i.tdate]
		if len(Transaction.objects.filter(tdate__date=datetime.now().date(), service=u, register_id=i.register_id, status=1))%2 == len(Transaction.objects.filter(tdate__date=datetime.now().date(), service=u, register_id=i.register_id, status=0))%2:
			h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]+=[Transaction.objects.filter(tdate__date=datetime.now().date(), service=u, register_id=i.register_id, status=0).latest("id").tdate]
		else:
			h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]+=[0]
#		render(request, 'attendance/service.html', {'h':h}, content_type='text/html')		

	j=Total()
	j.date=datetime.now().date().strftime("%Y-%m-%d")
	j.service=u
	g=j.LTotal()	
	
	return render(request, 'attendance/service.html', {'h':h, 'u':u, 'r':range(0, 5), 'g':g, 'nxtgnuser':nxtgnuser}, content_type='text/html')		

def level(request, m, u):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	h={}
	for i in Transaction.objects.filter(tdate__date=datetime.now().date(), service=m, level=u, status=1).distinct('register_id'):
		h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]=[i.level, i.tdate]
		if len(Transaction.objects.filter(tdate__date=datetime.now().date(), service=m, level=u, register_id=i.register_id, status=1))%2 == len(Transaction.objects.filter(tdate__date=datetime.now().date(), service=m, level=u, register_id=i.register_id, status=0))%2:
			h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]+=[Transaction.objects.filter(tdate__date=datetime.now().date(), service=m, level=u, register_id=i.register_id, status=0).latest("id").tdate]
		else:
			h[", ".join([Register.objects.get(id=i.register_id).lastname, Register.objects.get(id=i.register_id).firstname])]+=[0]
	return render(request, 'attendance/level.html', {'h':h, 'm':m, 'u':u, 'nxtgnuser':nxtgnuser}, content_type='text/html')

